import os
import csv
import re


def eval():
    pred_csv = "pred_results/pred_benchmark.csv"
    pred_summary = "pred_results/pred_benchmark_summary.txt"

    # Step 1: Verify output file existence
    if not os.path.isfile(pred_csv):
        return (False, f"Missing output file: {pred_csv}")
    if not os.path.isfile(pred_summary):
        return (False, f"Missing output file: {pred_summary}")

    # Step 2: Load and parse pred CSV
    try:
        with open(pred_csv, "r") as fh:
            reader = csv.DictReader(fh)
            pred_rows = list(reader)
            pred_columns = set(reader.fieldnames or [])
    except Exception as <local-path>        return (False, f"Failed to parse pred CSV: {e}")

    if len(pred_rows) == 0:
        return (False, "pred CSV has no data rows")

    # Step 3: Check for required column categories (flexible naming)
    # Framework column
    framework_col = None
    for candidate in ["framework", "Framework", "framework_name"]:
        if candidate in pred_columns:
            framework_col = candidate
            break
    if framework_col is None:
        return (False, f"No framework column found. Columns: {pred_columns}")

    # Timing columns - check at least some timing measurements exist
    timing_cols_found = []
    for col in pred_columns:
        col_lower = col.lower()
        if any(t in col_lower for t in ["setup_time", "build_time", "sim_time", "total_time",
                                         "setup", "build", "simulation", "timing"]):
            timing_cols_found.append(col)

    if len(timing_cols_found) < 2:
        return (False, f"Too few timing columns found (need ≥2): {pred_columns}")

    # Spike count column
    spike_col = None
    for candidate in ["spikes", "spike_count", "n_spikes", "total_spikes", "spikes_count"]:
        if candidate in pred_columns:
            spike_col = candidate
            break

    # Status column
    status_col = None
    for candidate in ["status", "execution_status", "run_status", "success"]:
        if candidate in pred_columns:
            status_col = candidate
            break

    # Step 4: Check framework coverage
    frameworks_tested = set(r[framework_col] for r in pred_rows if r.get(framework_col))
    if len(frameworks_tested) < 2:
        return (False, f"Only {len(frameworks_tested)} frameworks tested (need ≥2): {frameworks_tested}")

    # Check that at least some expected framework types are present
    framework_str = " ".join(frameworks_tested).lower()
    framework_types = []
    if any(kw in framework_str for kw in ["brian2", "brian"]):
        framework_types.append("Brian2")
    if any(kw in framework_str for kw in ["pytorch", "torch"]):
        framework_types.append("PyTorch")
    if any(kw in framework_str for kw in ["nest"]):
        framework_types.append("NEST")
    if any(kw in framework_str for kw in ["cuda", "gpu"]):
        framework_types.append("GPU")

    if len(frameworks_tested) < 2:
        return (False, f"Need at least 2 different frameworks, found: {frameworks_tested}")

    # Step 5: Check multiple simulation configurations (sizes or durations)
    # Look for variation in parameters
    param_col = None
    for candidate in ["simulation_parameters", "n_run", "network_size", "size", "t_run",
                      "duration", "parameters", "config"]:
        if candidate in pred_columns:
            param_col = candidate
            break

    # Check that there are multiple distinct configurations
    if param_col:
        param_values = set(r.get(param_col, "") for r in pred_rows)
        if len(param_values) < 2:
            return (False, f"Only {len(param_values)} distinct parameter values (need ≥2): {param_values}")

    # Step 6: Validate data quality - check timing values are numeric
    invalid_timing = 0
    valid_timing = 0
    for row in pred_rows:
        for col in timing_cols_found:
            val = row.get(col, "")
            if val == "" or val is None:
                continue
            try:
                float_val = float(val)
                if float_val >= 0:
                    valid_timing += 1
                else:
                    invalid_timing += 1
            except (ValueError, TypeError):
                invalid_timing += 1

    if valid_timing == 0:
        return (False, "No valid timing values found in CSV")

    if invalid_timing > valid_timing:
        return (False, f"Too many invalid timing values: {invalid_timing} invalid vs {valid_timing} valid")

    # Step 7: Check success/status if column exists
    if status_col:
        success_count = 0
        total_count = len(pred_rows)
        for row in pred_rows:
            status_val = str(row.get(status_col, "")).strip().lower()
            if status_val in ["success", "true", "1", "ok", "passed", "completed"]:
                success_count += 1
        success_rate = success_count / total_count if total_count > 0 else 0
        if success_rate < 0.5:
            return (False, f"Success rate {success_rate:.1%} below 50% ({success_count}/{total_count})")
    else:
        success_count = len(pred_rows)
        total_count = len(pred_rows)

    # Step 8: Check spike counts if column exists
    if spike_col:
        invalid_spikes = 0
        for row in pred_rows:
            val = row.get(spike_col, "")
            if val == "" or val is None:
                continue
            try:
                spike_val = float(val)
                if spike_val < 0:
                    invalid_spikes += 1
            except (ValueError, TypeError):
                invalid_spikes += 1
        if invalid_spikes > len(pred_rows) * 0.5:
            return (False, f"Too many invalid spike count values: {invalid_spikes}/{len(pred_rows)}")

    # Step 9: Check that we have enough rows
    # At minimum: 2 frameworks × 2 sizes × 2 durations = 8 rows
    if len(pred_rows) < 8:
        return (False, f"Too few data rows: {len(pred_rows)} (need ≥8 for meaningful benchmark)")

    # Step 10: Validate summary file
    try:
        with open(pred_summary, "r") as fh:
            summary_text = fh.read()
    except Exception as <local-path>        return (False, f"Failed to read pred summary: {e}")

    if len(summary_text) < 50:
        return (False, f"Summary file too short ({len(summary_text)} chars, need ≥50)")

    # Check summary mentions at least some framework names
    summary_lower = summary_text.lower()
    frameworks_in_summary = sum(
        1 for fw in frameworks_tested
        if fw.lower() in summary_lower or fw.lower()[:5] in summary_lower
    )
    if frameworks_in_summary < 1:
        return (False, f"Summary does not mention any tested frameworks. "
                       f"Frameworks: {frameworks_tested}")

    # Check summary has some numeric content (timing data)
    numbers_in_summary = re.findall(r'\d+\.?\d*', summary_text)
    if len(numbers_in_summary) < 5:
        return (False, f"Summary has too few numeric values ({len(numbers_in_summary)}), "
                       f"expected timing/count data")

    # Step 11: Check that fly-brain data was actually used
    # The CSV should have neuron counts or connection data reflecting the actual dataset
    # We just verify the benchmark ran with meaningful data by checking row count
    # The fly-brain dataset has 783 neurons, so active_neurons or similar should reflect this
    # (flexible check - just ensure data was loaded and used)

    return (True, f"Evaluation passed: {len(pred_rows)} benchmark rows, "
                  f"{len(frameworks_tested)} frameworks tested ({', '.join(sorted(frameworks_tested))}), "
                  f"{success_count}/{total_count} runs recorded as successful, "
                  f"timing data validated, summary report generated.")


if __name__ == "__main__":
    result, reason = eval()
    print(f"Result: {'PASS' if result else 'FAIL'}")
    print(f"Reason: {reason}")

import os
import numpy as np

# Original threshold: valid GMM params, avg log-likelihood > uniform - 5 (pass)


def parse_param_line(line, prefix):
    """Parse a line like 'pi=[v1,v2,...]' and return list of floats."""
    line = line.strip()
    if not line.startswith(prefix + '='):
        return None
    value_str = line[len(prefix) + 1:]
    value_str = value_str.strip('[]')
    try:
        return [float(x.strip()) for x in value_str.split(',')]
    except ValueError:
        return None


def load_params(filepath):
    """Load pi and sigma2 from a ParaLearn output file."""
    with open(filepath, 'r') as <local-path>        lines = [l.strip() for l in f.readlines() if l.strip()]

    pi = None
    sigma2 = None
    for line in lines:
        if line.startswith('pi='):
            pi = parse_param_line(line, 'pi')
        elif line.startswith('sigma2='):
            sigma2 = parse_param_line(line, 'sigma2')

    return pi, sigma2


def load_data(data_path):
    """Load mismatch data from the dataset."""
    data = []
    with open(data_path, 'r') as <local-path>        for line in <local-path>            for v in line.strip().split('\t'):
                v = v.strip()
                if <local-path>                    try:
                        data.append(float(v))
                    except ValueError:
                        pass
    return data


def eval():
    pred_path = 'pred_results/pred_ParaLearn.txt'
    gold_path = 'gold_results/pred_ParaLearn.txt'
    data_path = 'benchmark/datasets/De-anonymization-of-Mobility-Trajectories/pLearn4GMB/Mismatches'
    threshold = 20

    if not os.path.exists(pred_path):
        return (False, "Prediction file not found: pred_results/pred_ParaLearn.txt")

    try:
        pred_pi, pred_sigma2 = load_params(pred_path)
    except Exception as <local-path>        return (False, f"Failed to parse prediction file: {e}")

    if pred_pi is None or pred_sigma2 is None:
        return (False, "Could not parse pi or sigma2 from prediction file")

    pred_pi = np.array(pred_pi)
    pred_sigma2 = np.array(pred_sigma2)

    if len(pred_pi) < 1 or len(pred_pi) != len(pred_sigma2):
        return (False, f"Invalid parameter dimensions: pi has {len(pred_pi)}, sigma2 has {len(pred_sigma2)}")

    if not (0.95 <= np.sum(pred_pi) <= 1.05):
        return (False, f"Pi does not sum to ~1: sum = {np.sum(pred_pi):.6f}")
    if np.any(pred_pi < -1e-10):
        return (False, "Pi contains negative values")

    if np.any(pred_sigma2 <= 0):
        return (False, "Sigma2 contains non-positive values")

    try:
        data = load_data(data_path)
    except Exception as <local-path>        return (False, f"Failed to load dataset: {e}")

    # Compare against gold result if available
    gold_pi, gold_sigma2 = None, None
    if os.path.exists(gold_path):
        try:
            gold_pi, gold_sigma2 = load_params(gold_path)
            gold_pi = np.array(gold_pi)
            gold_sigma2 = np.array(gold_sigma2)
        except Exception:
            pass

    if gold_pi is not None and gold_sigma2 is not None and len(pred_pi) == len(gold_pi):
        pi_diff = np.max(np.abs(pred_pi - gold_pi))
        sigma2_diff = np.max(np.abs(pred_sigma2 - gold_sigma2))
        if pi_diff < 0.05 and sigma2_diff < 5.0:
            return (True, f"Parameters match gold closely: max pi diff = {pi_diff:.6f}, max sigma2 diff = {sigma2_diff:.4f}")
        elif pi_diff < 0.15 and sigma2_diff < 50.0:
            return (True, f"Parameters reasonably close to gold: max pi diff = {pi_diff:.6f}, max sigma2 diff = {sigma2_diff:.4f}")

    if pred_pi.sum() < 0.5:
        return (False, f"Pi values sum to only {pred_pi.sum():.4f}, EM likely did not converge")

    if np.any(np.isnan(pred_pi)) or np.any(np.isnan(pred_sigma2)):
        return (False, "NaN values in parameters, EM diverged")

    return (True, f"Valid GMM parameters: {len(pred_pi)} components, pi sums to {pred_pi.sum():.4f}")


if __name__ == '__main__':
