    print(f"Reason: {reason}")

import os
import json
import pandas as pd
import numpy as np
from sklearn.metrics import roc_auc_score, accuracy_score, f1_score, average_precision_score


def eval():
    pred_csv = "pred_results/pred_run_kancd_demo.csv"
    pred_json = "pred_results/pred_run_kancd_demo_summary.json"

    # Check predicted files exist
    for f in [pred_csv, pred_json]:
        if not os.path.exists(f):
            return (False, f"Missing predicted output file: {f}")

    # Load predicted outputs
    try:
        pred_df = pd.read_csv(pred_csv)
    except Exception as <local-path>        return (False, f"Failed to read predicted CSV: {e}")

    try:
        with open(pred_json, "r") as fh:
            pred_summary = json.load(fh)
    except Exception as <local-path>        return (False, f"Failed to read predicted JSON: {e}")

    # --- Validate CSV structure ---
    # Accept common column name variants
    required_cols_variants = {
        "student_id": ["student_id"],
        "exercise_id": ["exercise_id"],
        "actual": ["actual", "actual_response", "actual_score"],
        "predicted": ["predicted", "predicted_response", "predicted_score"],
        "probability": ["probability", "probability_score", "prob", "pred_prob"],
    }

    col_mapping = {}
    for canonical, variants in required_cols_variants.items():
        found = [v for v in variants if v in pred_df.columns]
        if not found:
            return (False, f"Missing required column (expected one of {variants}) in predicted CSV. Found columns: {list(pred_df.columns)}")
        col_mapping[canonical] = found[0]

    # Rename to canonical names for uniform processing
    pred_df = pred_df.rename(columns={v: k for k, v in col_mapping.items()})

    # --- Validate data integrity ---
    # Check for missing values in key columns
    for col in ["student_id", "exercise_id", "actual", "predicted", "probability"]:
        if pred_df[col].isna().any():
            return (False, f"Missing values found in column '{col}' of predicted CSV")

    # Check probability scores are in [0, 1]
    probs = pred_df["probability"].values
    if np.any(probs < 0) or np.any(probs > 1):
        return (False, "Probability scores outside [0, 1] range detected")

    # Check actual values are binary (0 or 1)
    actual_vals = pred_df["actual"].unique()
    if not set(actual_vals).issubset({0, 1}):
        return (False, f"Actual response values should be 0 or 1, found: {actual_vals}")

    # Check predicted values are binary (0 or 1)
    pred_vals = pred_df["predicted"].unique()
    if not set(pred_vals).issubset({0, 1}):
        return (False, f"Predicted response values should be 0 or 1, found: {pred_vals}")

    # --- Check prediction count ---
    if len(pred_df) == 0:
        return (False, "Predicted CSV is empty")

    # --- Calculate classification metrics ---
    y_true = pred_df["actual"].values
    y_pred = pred_df["predicted"].values
    y_prob = pred_df["probability"].values

    # Need both classes present for AUROC
    if len(np.unique(y_true)) < 2:
        return (False, "Only one class present in actual values; cannot compute AUROC")

    try:
        auroc = roc_auc_score(y_true, y_prob)
    except Exception as <local-path>        return (False, f"Failed to compute AUROC: {e}")

    try:
        auprc = average_precision_score(y_true, y_prob)
    except Exception as <local-path>        return (False, f"Failed to compute AUPRC: {e}")

    accuracy = accuracy_score(y_true, y_pred)
    f1 = f1_score(y_true, y_pred, zero_division=0)

    # --- Validate against thresholds ---
    failures = []
    if auroc < 0.55:
        failures.append(f"AUROC={auroc:.4f} < 0.55 (minimum threshold)")
    if accuracy < 0.55:
        failures.append(f"Accuracy={accuracy:.4f} < 0.55 (minimum threshold)")

    # --- Validate JSON summary ---
    # Look for accuracy-related keys with flexible naming
    accuracy_keys = ["accuracy", "model_accuracy", "test_accuracy", "acc"]
    found_accuracy_key = next((k for k in accuracy_keys if k in pred_summary), None)

    # Look for total interactions with flexible naming
    interaction_keys = ["total_interactions", "total_interactions_processed", "num_interactions", "interactions"]
    found_interactions_key = next((k for k in interaction_keys if k in pred_summary), None)

    # Look for configuration/config with flexible naming
    config_keys = ["config", "configuration", "params", "parameters", "settings"]
    found_config_key = next((k for k in config_keys if k in pred_summary), None)

    json_issues = []

    if found_accuracy_key is None:
        json_issues.append(f"Missing accuracy field in summary JSON (tried: {accuracy_keys})")
    else:
        # Validate accuracy value is reasonable
        json_acc = pred_summary[found_accuracy_key]
        if not isinstance(json_acc, (int, float)):
            json_issues.append(f"Accuracy value '{json_acc}' is not numeric")
        elif not (0.0 <= json_acc <= 1.0):
            json_issues.append(f"Accuracy value {json_acc} is outside [0, 1] range")
        else:
            # Check it roughly matches computed accuracy (within 5%)
            if abs(json_acc - accuracy) > 0.05:
                json_issues.append(
                    f"Summary accuracy ({json_acc:.4f}) differs significantly from computed accuracy ({accuracy:.4f})"
                )

    if found_interactions_key is None:
        json_issues.append(f"Missing total interactions field in summary JSON (tried: {interaction_keys})")
    else:
        reported_count = pred_summary[found_interactions_key]
        if reported_count != len(pred_df):
            json_issues.append(
                f"Reported interactions ({reported_count}) does not match CSV row count ({len(pred_df)})"
            )

    if found_config_key is None:
        json_issues.append(f"Missing configuration field in summary JSON (tried: {config_keys})")

    if json_issues:
        return (False, "JSON summary validation failed: " + "; ".join(json_issues))

    # --- Build result message ---
    metrics_msg = (
        f"AUROC={auroc:.4f}, Accuracy={accuracy:.4f}, F1={f1:.4f}, AUPRC={auprc:.4f}, "
        f"Predictions={len(pred_df)}"
    )

    if failures:
        return (False, f"Minimum thresholds not met. {metrics_msg}. Issues: {'; '.join(failures)}")

    # Warn about secondary thresholds but don't fail
    warnings = []
    if auroc < 0.70:
        warnings.append(f"AUROC={auroc:.4f} below recommended 0.70")
    if accuracy < 0.65:
        warnings.append(f"Accuracy={accuracy:.4f} below recommended 0.65")
    if f1 < 0.60:
        warnings.append(f"F1={f1:.4f} below recommended 0.60")

    if warnings:
        return (True, f"Minimum thresholds met but some recommended thresholds missed. {metrics_msg}. Warnings: {'; '.join(warnings)}")

    return (True, f"All thresholds met. {metrics_msg}")


if __name__ == "__main__":
    passed, reason = eval()
    print(f"Result: {passed}")
    print(f"Reason: {reason}")

import json
import os
import csv
import math


def find_value_by_aliases(d, *aliases):
    """Find a value in dict by trying multiple key aliases."""
    for alias in aliases:
        if alias in <local-path>            return d[alias], alias
    return None, None


def eval():
    pred_json_path = "pred_results/pred_ECDDataTPL.json"
    pred_csv_path = "pred_results/pred_ECDDataTPL.csv"
    gold_json_path = "./gold_results/pred_ECDDataTPL.json"
    gold_csv_path = "./gold_results/pred_ECDDataTPL.csv"

    # Step 1: Verify output files exist
    for path, label in [(pred_json_path, "Predicted JSON"), (pred_csv_path, "Predicted CSV")]:
        if not os.path.exists(path):
            return (False, f"{label} file not found: {path}")

    # Load predicted JSON
    try:
        with open(pred_json_path, 'r') as <local-path>            pred = json.load(f)
    except (json.JSONDecodeError, Exception) as <local-path>        return (False, f"Failed to parse predicted JSON: {e}")

    # Load gold files if available
    gold = None
    gold_csv_rows = None
    gold_csv_cols = None

    if os.path.exists(gold_json_path):
        try:
            with open(gold_json_path, 'r') as <local-path>                gold = json.load(f)
        except Exception as <local-path>            gold = None

    if os.path.exists(gold_csv_path):
        try:
            with open(gold_csv_path, 'r') as <local-path>                reader = csv.DictReader(f)
                gold_csv_rows = list(reader)
                gold_csv_cols = reader.fieldnames
        except Exception:
            gold_csv_rows = None

    # Step 2: Check JSON has required content - flexible key matching
    # Find question count
    q_count_val, q_count_key = find_value_by_aliases(
        pred, 'qqq_count', 'question_count', 'num_questions', 'n_questions', 'question_num'
    )
    if q_count_val is None:
        return (False, f"Could not find question count in JSON. Keys present: {list(pred.keys())}")

    try:
        q_count = int(q_count_val)
    except (TypeError, ValueError):
        return (False, f"Question count must be numeric, got: {q_count_val}")

    if q_count <= 0:
        return (False, f"Question count must be positive, got: {q_count}")

    # Find Q-matrix
    q_mat_val, q_mat_key = find_value_by_aliases(
        pred, 'Q_mat', 'q_matrix', 'q_matrix_values', 'Q_matrix', 'qmatrix'
    )
    if q_mat_val is None:
        return (False, f"Could not find Q-matrix in JSON. Keys present: {list(pred.keys())}")

    if not isinstance(q_mat_val, list):
        return (False, f"Q-matrix must be a list of lists, got: {type(q_mat_val)}")

    if len(q_mat_val) == 0:
        return (False, "Q-matrix is empty")

    # Check Q-matrix is 2D
    if not isinstance(q_mat_val[0], list):
        return (False, "Q-matrix must be 2D (list of lists)")

    q_mat_rows = len(q_mat_val)
    q_mat_cols = len(q_mat_val[0])

    # Find Q-matrix shape/dimensions
    q_shape_val, q_shape_key = find_value_by_aliases(
        pred, 'Q_mat_shape', 'q_matrix_shape', 'q_matrix_dimensions', 'Q_mat_dimensions', 'qmatrix_shape'
    )
    if q_shape_val is not None:
        if isinstance(q_shape_val, (list, tuple)) and len(q_shape_val) == 2:
            shape_rows = int(q_shape_val[0])
            shape_cols = int(q_shape_val[1])
            if shape_rows != q_mat_rows or shape_cols != q_mat_cols:
                return (False, f"Q-matrix shape {q_shape_val} doesn't match actual matrix dimensions [{q_mat_rows}, {q_mat_cols}]")

    # Find question groupings
    groups_val, groups_key = find_value_by_aliases(
        pred, 'qqq_group_list', 'question_groups', 'question_groupings', 'concept_groups', 
        'qqq_groups', 'groups', 'concept_question_groups'
    )
    if groups_val is None:
        return (False, f"Could not find question groupings in JSON. Keys present: {list(pred.keys())}")

    # Normalize groups to list of lists (handle dict with int/str keys)
    if isinstance(groups_val, dict):
        # Convert dict to sorted list of lists
        try:
            sorted_keys = sorted(groups_val.keys(), key=lambda x: int(x))
            groups_list = [groups_val[k] for k in sorted_keys]
        except (ValueError, TypeError):
            groups_list = list(groups_val.values())
    elif isinstance(groups_val, list):
        groups_list = groups_val
    else:
        return (False, f"Question groupings must be a list or dict, got: {type(groups_val)}")

    # Find question list
    q_list_val, q_list_key = find_value_by_aliases(
        pred, 'qqq_list', 'question_list', 'question_list_data', 'questions', 'exercise_list',
        'question_ids', 'qqq_list_data'
    )
    if q_list_val is None:
        return (False, f"Could not find question list in JSON. Keys present: {list(pred.keys())}")

    if not isinstance(q_list_val, list):
        return (False, f"Question list must be a list, got: {type(q_list_val)}")

    # Find student data info
    student_data_val, student_data_key = find_value_by_aliases(
        pred, 'student_data_shape', 'student_data_statistics', 'student_statistics', 
        'student_data', 'student_info', 'students_info'
    )
    if student_data_val is None:
        return (False, f"Could not find student data info in JSON. Keys present: {list(pred.keys())}")

    # Step 3: Cross-validate internal consistency
    # Q-matrix rows should match question count
    if q_mat_rows != q_count:
        return (False, f"Q-matrix row count ({q_mat_rows}) doesn't match question count ({q_count})")

    # Q-matrix columns should match number of groups (concepts)
    if len(groups_list) != q_mat_cols:
        # This might be acceptable if groups are indexed differently, just warn
        pass  # Don't fail on this, different implementations may organize differently

    # Question list should have at least as many entries as unique questions
    if len(q_list_val) < q_count:
        return (False, f"Question list length ({len(q_list_val)}) less than question count ({q_count})")

    # Q-matrix values should be 0 or 1 (binary)
    for i, row in enumerate(q_mat_val):
        for j, val in enumerate(row):
            if val not in [0, 1, 0.0, 1.0]:
                return (False, f"Q-matrix values should be binary (0 or 1), got {val} at [{i}][{j}]")

