import os
import numpy as np
import pandas as pd
import torch
import torch.nn as nn
import nibabel as nib
from sklearn.metrics import roc_auc_score

# Original threshold: AUROC >= 0.55, within 0.30 of gold (pass)

DATA_CSV = 'benchmark/datasets/BrainIAC/data/csvs/sample.csv'
DATA_ROOT = 'benchmark/datasets/BrainIAC/src/data/sample/processed/'
IMAGE_SIZE = (64, 64, 64)


class ViTBackboneNet(nn.Module):
    def __init__(self):
        super().__init__()
        self.features = nn.Sequential(
            nn.Conv3d(1, 64, kernel_size=7, stride=2, padding=3),
            nn.ReLU(inplace=True),
            nn.MaxPool3d(kernel_size=3, stride=2, padding=1),
            nn.AdaptiveAvgPool3d((1, 1, 1)),
            nn.Flatten(),
            nn.Linear(64, 768),
        )

    def forward(self, x):
        return self.features(x)


class Classifier(nn.Module):
    def __init__(self, d_model=768, num_classes=1):
        super().__init__()
        self.classifier = nn.Linear(d_model, num_classes)

    def forward(self, x):
        return self.classifier(x)


class SingleScanModelBP(nn.Module):
    def __init__(self, backbone, classifier):
        super().__init__()
        self.backbone = backbone
        self.classifier = classifier

    def forward(self, x):
        features = self.backbone(x)
        return self.classifier(features)


def build_model():
    backbone = ViTBackboneNet()
    classifier = Classifier(d_model=768, num_classes=1)
    return SingleScanModelBP(backbone, classifier)


def load_model(checkpoint_path):
    try:
        checkpoint = torch.load(checkpoint_path, map_location='cpu', weights_only=False)
        if not isinstance(checkpoint, dict) or 'model_state_dict' not in checkpoint:
            return None
        model = build_model()
        model.load_state_dict(checkpoint['model_state_dict'])
        model.eval()
        return model
    except Exception:
        return None


def compute_auroc(model):
    if not os.path.exists(DATA_CSV) or not os.path.isdir(DATA_ROOT):
        return None

    df = pd.read_csv(DATA_CSV)
    preds = []
    labels = []

    with torch.no_grad():
        for _, row in df.iterrows():
            img_path = os.path.join(DATA_ROOT, row.iloc[0])
            label = int(row.iloc[-1])

            try:
                nii = nib.load(img_path)
                image = torch.FloatTensor(nii.get_fdata()).unsqueeze(0)
                image = torch.nn.functional.interpolate(
                    image.unsqueeze(0), size=IMAGE_SIZE, mode='trilinear', align_corners=False
                )
                logits = model(image)
                prob = torch.sigmoid(logits).item()
                preds.append(prob)
                labels.append(label)
            except Exception:
                return None

    if len(set(labels)) < 2:
        return None

    try:
        return roc_auc_score(labels, preds)
    except Exception:
        return None


def eval():
    pred_model_path = 'pred_results/best_model.pth'
    gold_model_path = 'gold_results/best_model.pth'

    if not os.path.exists(pred_model_path):
        return (False, "Prediction model not found: pred_results/best_model.pth")

    pred_model = load_model(pred_model_path)
    if pred_model is None:
        return (False, "Failed to load prediction model")

    pred_auroc = compute_auroc(pred_model)
    if pred_auroc is None:
        return (False, "Failed to compute AUROC for prediction model")

    if pred_auroc < 0.55:
        return (False, f"AUROC = {pred_auroc:.4f} is below minimum threshold of 0.55")

    if not os.path.exists(gold_model_path):
        if pred_auroc >= 0.55:
            return (True, f"AUROC = {pred_auroc:.4f} (threshold >= 0.55, gold model not available for proximity check)")
        return (False, f"AUROC = {pred_auroc:.4f}, gold model not available")

    gold_model = load_model(gold_model_path)
    if gold_model is None:
        if pred_auroc >= 0.55:
            return (True, f"AUROC = {pred_auroc:.4f} (threshold >= 0.55, could not load gold model for proximity check)")
        return (False, f"AUROC = {pred_auroc:.4f}, could not load gold model")

    gold_auroc = compute_auroc(gold_model)
    if gold_auroc is None:
        if pred_auroc >= 0.55:
            return (True, f"AUROC = {pred_auroc:.4f} (threshold >= 0.55, could not compute gold AUROC for proximity check)")
        return (False, f"AUROC = {pred_auroc:.4f}, could not compute gold AUROC")

    diff = abs(pred_auroc - gold_auroc)
    if pred_auroc >= 0.55 and diff <= 0.30:
        return (True, f"AUROC = {pred_auroc:.4f}, gold AUROC = {gold_auroc:.4f}, diff = {diff:.4f} (thresholds: >= 0.55, within 0.30 of gold)")
    else:
        return (False, f"AUROC = {pred_auroc:.4f}, gold AUROC = {gold_auroc:.4f}, diff = {diff:.4f} (thresholds: >= 0.55, within 0.30 of gold)")


