import scipy.io as scio

PRED_PDF = "pred_results/pred_Fig13(b)-Performance-of-channel-estimation-SNR.pdf"
GOLD_PDF = "./gold_results/pred_Fig13(b)-Performance-of-channel-estimation-SNR.pdf"
MAT_FILE = "benchmark/datasets/RF-Diffusion/plots/data/exp_mimo_snr.mat"


def extract_pdf_text(pdf_path):
    """Try to extract text from PDF using available libraries."""
    # Try pypdf first (handles rotated/vertical text well)
    try:
        from pypdf import PdfReader
        reader = PdfReader(pdf_path)
        text = ""
        for page in reader.pages:
            text += page.extract_text() or ""
        if text.strip():
            return text
    except ImportError:
        pass

    # Try PyMuPDF (fitz)
    try:
        import fitz
        doc = fitz.open(pdf_path)
        text = ""
        for page in doc:
            text += page.get_text()
        doc.close()
        if text.strip():
            return text
    except ImportError:
        pass

    # Try pdfminer
    try:
        from pdfminer.high_level import extract_text
        text = extract_text(pdf_path)
        if text.strip():
            return text
    except ImportError:
        pass

    # Try PyPDF2
    try:
        import PyPDF2
        reader = PyPDF2.PdfReader(pdf_path)
        text = ""
        for page in reader.pages:
            text += page.extract_text() or ""
        if text.strip():
            return text
    except ImportError:
        pass

    return None


def eval():
    # 1. Check predicted PDF exists
    if not os.path.isfile(PRED_PDF):
        return (False, f"Predicted PDF not found at {PRED_PDF}")

    # Check file is a valid PDF (starts with %PDF)
    with open(PRED_PDF, "rb") as <local-path>        header = f.read(5)
    if header != b"%PDF-":
        return (False, "Output file is not a valid PDF")

    # Check file is non-trivial in size (at least 1KB)
    pred_size = os.path.getsize(PRED_PDF)
    if pred_size < 1024:
        return (False, f"PDF file is too small ({pred_size} bytes), likely empty or corrupt")

    # 2. Load source data to validate data integrity
    if not os.path.isfile(MAT_FILE):
        return (False, f"Source data file not found at {MAT_FILE}")

    mat_data = scio.loadmat(MAT_FILE)
    data_rf = mat_data["RF-Diffusion"][0]
    data_nerf2 = mat_data["data_nerf2"][0]
    data_fire = mat_data["data_fire"][0]
    data_codebook = mat_data["data_codebook"][0]

    # Verify expected sample counts
    expected = {"RF-Diffusion": (data_rf, 2300), "NeRF2": (data_nerf2, 160),
                "FIRE": (data_fire, 101), "Codebook": (data_codebook, 2000)}
    for name, (arr, exp_len) in expected.items():
        if len(arr) != exp_len:
            return (False, f"{name} has {len(arr)} samples, expected {exp_len}")

    # 3. Try to extract and check PDF text content
    text = extract_pdf_text(PRED_PDF)
    if text is not None and len(text.strip()) > 0:
        # Collapse whitespace/newlines for matching (some extractors split vertical text char-by-char)
        text_collapsed = text.replace("\n", "").replace(" ", "")

        # Check for SNR label (contiguous or split by newlines)
        has_snr = "SNR" in text or "SNR" in text_collapsed or "snr" in text_collapsed.lower()
        if not has_snr:
            return (False, "Y-axis label 'SNR' not found in the PDF")

        # Check method labels - at least 2 should be present
        method_found = 0
        for method in ["RF-Diffusion", "Diffusion", "FIRE", "Codebook", "NeRF"]:
            if method in text or method in text_collapsed:
                method_found += 1
        if method_found < 2:
            return (False, f"Only {method_found}/4 method labels found in PDF text")

    # 4. Compare with gold PDF if available (size-based sanity check)
    if os.path.isfile(GOLD_PDF):
        gold_size = os.path.getsize(GOLD_PDF)
        ratio = pred_size / gold_size if gold_size > 0 else 0
        # Allow generous tolerance - different renderers/fonts produce different sizes
        if ratio < 0.1 or ratio > 10:
            return (False, f"PDF size ratio ({ratio:.2f}) is far from gold, suggesting very different content")

    return (True, "PDF exists with correct format, source data has correct sample counts (RF-Diffusion:2300, NeRF2:160, FIRE:101, Codebook:2000)")


