import os
import math


def eval():
    pred_path = "pred_results/pred_npscorer.txt"
    gold_path = "./gold_results/pred_npscorer.txt"

    # Step 1: Check file existence
    if not os.path.exists(pred_path):
        return (False, f"Predicted output file '{pred_path}' does not exist.")
    if not os.path.exists(gold_path):
        return (False, f"Gold output file '{gold_path}' does not exist.")

    # Parse a results file into list of (smiles, name, score) tuples
    def parse_file(filepath):
        rows = []
        with open(filepath, 'r') as <local-path>            lines = f.readlines()
        if not lines:
            return rows, "File is empty"

        start = 0
        # Skip header if present
        first_parts = lines[0].strip().split('\t')
        if len(first_parts) >= 3 and first_parts[-1].replace('.', '').replace('-', '').replace('+', '').replace('e', '').replace('E', '').lstrip('-').isdigit() is False:
            start = 1
        # More robust header detection
        if first_parts[0].upper() == 'SMILES' or first_parts[-1].upper() == 'NP_SCORE':
            start = 1

        for i in range(start, len(lines)):
            line = lines[i].strip()
            if not line:
                continue
            parts = line.split('\t')
            if len(parts) < 3:
                return rows, f"Line {i+1} has {len(parts)} columns, expected 3"
            smiles = parts[0].strip()
            name = parts[1].strip()
            try:
                score = float(parts[2].strip())
            except ValueError:
                return rows, f"Line {i+1}: NP_Score '{parts[2]}' is not a valid number"
            if math.isnan(score) or math.isinf(score):
                return rows, f"Line {i+1}: NP_Score is NaN or Inf"
            rows.append((smiles, name, score))
        return rows, None

    gold_rows, gold_err = parse_file(gold_path)
    if gold_err:
        return (False, f"Error parsing gold file: {gold_err}")
    if not gold_rows:
        return (False, "Gold file contains no data rows.")

    pred_rows, pred_err = parse_file(pred_path)
    if pred_err:
        return (False, f"Error parsing predicted file: {pred_err}")
    if not pred_rows:
        return (False, "Predicted file contains no data rows.")

    # Step 2: Validate score range [-5, 5]
    for smiles, name, score in pred_rows:
        if score < -5 or score > 5:
            return (False, f"Score {score} for molecule '{name}' is outside valid range [-5, 5].")

    # Step 3: Check data completeness
    gold_count = len(gold_rows)
    pred_count = len(pred_rows)
    success_rate = pred_count / gold_count if gold_count > 0 else 0

    if success_rate < 0.95:
        return (False, f"Processing success rate {success_rate:.2%} ({pred_count}/{gold_count}) is below 95% threshold.")

    # Step 4: Compare scores against gold standard
    # Build lookup by molecule name for matching
    gold_by_name = {}
    for smiles, name, score in gold_rows:
        gold_by_name[name] = (smiles, score)

    pred_by_name = {}
    for smiles, name, score in pred_rows:
        pred_by_name[name] = (smiles, score)

    # Check how many gold molecules are matched and how close scores are
    matched = 0
    score_diffs = []
    large_diff_examples = []

    for name, (g_smiles, g_score) in gold_by_name.items():
        if name in pred_by_name:
            matched += 1
            p_smiles, p_score = pred_by_name[name]
            diff = abs(p_score - g_score)
            score_diffs.append(diff)
            if diff > 0.5:
                large_diff_examples.append((name, g_score, p_score, diff))

    match_rate = matched / gold_count if gold_count > 0 else 0

    if match_rate < 0.95:
        return (False, f"Only {match_rate:.2%} ({matched}/{gold_count}) of gold molecules found in predictions (need >= 95%).")

    # Check score agreement - allow small numerical differences from floating point
    # but flag large systematic differences
    if score_diffs:
        max_diff = max(score_diffs)
        mean_diff = sum(score_diffs) / len(score_diffs)

        # Tolerance: scores should be very close since the algorithm is deterministic
        tolerance = 0.1
        outliers = sum(1 for d in score_diffs if d > tolerance)
        outlier_rate = outliers / len(score_diffs)

        if outlier_rate > 0.05:
            examples_str = "; ".join(
                f"{n}: gold={gs:.3f}, pred={ps:.3f}"
                for n, gs, ps, d in large_diff_examples[:3]
            )
            return (False, f"Score mismatch: {outlier_rate:.1%} of molecules have score difference > {tolerance}. "
                          f"Mean diff: {mean_diff:.4f}, Max diff: {max_diff:.4f}. Examples: {examples_str}")

    # Step 5: All checks passed
    pred_scores = [s for _, _, s in pred_rows]
    min_s = min(pred_scores)
    max_s = max(pred_scores)
    mean_s = sum(pred_scores) / len(pred_scores)

    return (True, f"Evaluation passed. {pred_count} molecules processed ({success_rate:.0%} of gold). "
                  f"Score range: [{min_s:.3f}, {max_s:.3f}], mean: {mean_s:.3f}. "
                  f"{matched}/{gold_count} molecules matched by name.")


