import os
import re


def parse_fasta(path):
    """Parse a FASTA file, return list of (header, sequence) tuples."""
    entries = []
    header = None
    seq_lines = []
    with open(path) as <local-path>        for line in <local-path>            line = line.rstrip('\n')
            if line.startswith('>'):
                if header is not None:
                    entries.append((header, ''.join(seq_lines)))
                header = line[1:]
                seq_lines = []
            else:
                seq_lines.append(line)
        if header is not None:
            entries.append((header, ''.join(seq_lines)))
    return entries


def parse_report(path):
    """Parse the txt report file, return dict with extracted info."""
    with open(path) as <local-path>        content = f.read()

    info = {}

    # Extract total ORFs processed
    m = re.search(r'Total ORFs processed:\s*(\d+)', content)
    info['total_orfs'] = int(m.group(1)) if m else None

    # Extract spurious count
    m = re.search(r'(?:Discarded as spurious|spurious|Spurious)[:\s]*(\d+)', content, re.IGNORECASE)
    info['spurious_count'] = int(m.group(1)) if m else None

    # Check for ORF details section
    info['has_orf_details'] = bool(re.search(r'ORF\s+\d+|ORF Details', content, re.IGNORECASE))

    # Extract per-ORF info
    orf_blocks = re.findall(
        r'ORF\s+\d+.*?(?=ORF\s+\d+|Discarded ORFs|$)', content, re.DOTALL
    )
    info['orf_blocks'] = orf_blocks

    # Check for coordinate info in ORF blocks
    info['has_coordinates'] = bool(re.search(r'Start|start|Stop|stop|coordinates', content, re.IGNORECASE))

    # Check for strand info
    info['has_strand'] = bool(re.search(r'Strand|strand', content, re.IGNORECASE))

    # Check for status/classification
    info['has_status'] = bool(re.search(r'Status|KEPT|DISCARDED|spurious|valid', content, re.IGNORECASE))

    # Check for discarded summary section
    info['has_discarded_summary'] = bool(re.search(r'Discarded|Summary', content, re.IGNORECASE))

    return info


def eval():
    pred_faa = 'pred_results/pred_orf.faa'
    pred_txt = 'pred_results/pred_orf.txt'
    gold_faa = './gold_results/pred_orf.faa'
    gold_txt = './gold_results/pred_orf.txt'

    # Step 1: Check file existence
    for path, label in [(pred_faa, 'pred .faa'), (pred_txt, 'pred .txt'),
                         (gold_faa, 'gold .faa'), (gold_txt, 'gold .txt')]:
        if not os.path.isfile(path):
            return (False, f"Missing file: {label} ({path})")

    # Check non-empty
    for path, label in [(pred_faa, 'pred .faa'), (pred_txt, 'pred .txt')]:
        if os.path.getsize(path) == 0:
            return (False, f"Empty file: {label}")

    # Step 2: Parse FASTA files
    try:
        pred_seqs = parse_fasta(pred_faa)
    except Exception as <local-path>        return (False, f"Failed to parse predicted FASTA: {e}")

    try:
        gold_seqs = parse_fasta(gold_faa)
    except Exception as <local-path>        return (False, f"Failed to parse gold FASTA: {e}")

    if len(pred_seqs) == 0:
        return (False, "Predicted FASTA contains no sequences")

    # Validate FASTA format: check amino acid characters
    valid_aa = set('ACDEFGHIKLMNPQRSTVWY*')
    for header, seq in pred_seqs:
        invalid = set(seq.upper()) - valid_aa
        if invalid:
            return (False, f"Invalid amino acid characters {invalid} in sequence '{header}'")

    # Check unique headers
    pred_headers = [h for h, _ in pred_seqs]
    if len(pred_headers) != len(set(pred_headers)):
        return (False, "Duplicate headers in predicted FASTA")

    # Step 3: Parse reports
    try:
        pred_info = parse_report(pred_txt)
    except Exception as <local-path>        return (False, f"Failed to parse predicted report: {e}")

    try:
        gold_info = parse_report(gold_txt)
    except Exception as <local-path>        return (False, f"Failed to parse gold report: {e}")

    # Validate report has required fields
    if pred_info['total_orfs'] is None:
        return (False, "Predicted report missing total ORF count")

    if pred_info['spurious_count'] is None:
        return (False, "Predicted report missing spurious count")

    if not pred_info['has_orf_details']:
        return (False, "Predicted report missing per-ORF details section")

    if not pred_info['has_coordinates']:
        return (False, "Predicted report missing genomic coordinate information")

    if not pred_info['has_strand']:
        return (False, "Predicted report missing strand information")

    if not pred_info['has_status']:
        return (False, "Predicted report missing classification status for ORFs")

    # Step 4: Cross-validate consistency

    # Spurious count <= total count
    if pred_info['spurious_count'] > pred_info['total_orfs']:
        return (False, f"Spurious count ({pred_info['spurious_count']}) exceeds total ORF count ({pred_info['total_orfs']})")

    # FASTA sequence count should match total ORF count in report
    if len(pred_seqs) != pred_info['total_orfs']:
        return (False, f"FASTA sequence count ({len(pred_seqs)}) does not match total ORFs in report ({pred_info['total_orfs']})")

    # Step 5: Compare against gold standard

    # Check same number of sequences
    if len(pred_seqs) != len(gold_seqs):
        return (False, f"Predicted FASTA has {len(pred_seqs)} sequences, gold has {len(gold_seqs)}")

    # Compare actual sequences (order-independent)
    pred_seq_set = set(seq.upper() for _, seq in pred_seqs)
    gold_seq_set = set(seq.upper() for _, seq in gold_seqs)
    if pred_seq_set != gold_seq_set:
        missing = gold_seq_set - pred_seq_set
        extra = pred_seq_set - gold_seq_set
        msg = "Sequence mismatch."
        if missing:
            msg += f" Missing {len(missing)} gold sequence(s)."
        if extra:
            msg += f" {len(extra)} extra sequence(s) not in gold."
        return (False, msg)

    # Check total ORF count matches gold
    if gold_info['total_orfs'] is not None and pred_info['total_orfs'] != gold_info['total_orfs']:
        return (False, f"Total ORF count mismatch: pred={pred_info['total_orfs']}, gold={gold_info['total_orfs']}")

    # Check spurious count matches gold
    if gold_info['spurious_count'] is not None and pred_info['spurious_count'] != gold_info['spurious_count']:
        return (False, f"Spurious count mismatch: pred={pred_info['spurious_count']}, gold={gold_info['spurious_count']}")

    # Check discarded ORF details if any exist in gold
    # Read raw report content to check for E-value reporting on discarded ORFs
    with open(pred_txt) as <local-path>        pred_content = f.read()

    if pred_info['spurious_count'] > 0:
        # If there are spurious ORFs, check that E-value info is reported
        if not re.search(r'[Ee]-?value|evalue', pred_content, re.IGNORECASE):
            return (False, "Spurious ORFs detected but no E-value information in report")

    return (True, f"All checks passed. {len(pred_seqs)} ORFs validated, {pred_info['spurious_count']} spurious. Sequences and counts match gold standard.")


