import os
import re
import numpy as np
import pandas as pd


def eval():
    pred_path = 'pred_results/pred_boxmodel.txt'
    conc_path = 'benchmark/datasets/ISAT/conc_data.txt'
    irr_path = 'benchmark/datasets/ISAT/irr_data.txt'

    # Check existence
    if not os.path.exists(pred_path):
        return (False, "Predicted output file pred_results/pred_boxmodel.txt does not exist")

    # Check non-empty
    if os.path.getsize(pred_path) == 0:
        return (False, "Predicted output file is empty")

    # Read source data to verify correctness
    try:
        conc_df = pd.read_csv(conc_path, sep='\t', comment='#', header=0)
        irr_df = pd.read_csv(irr_path, sep='\t', comment='#', header=0)
    except Exception as <local-path>        return (False, f"Could not read source data files: {e}")

    # Read predicted output
    try:
        with open(pred_path, 'r') as <local-path>            content = f.read()
    except Exception as <local-path>        return (False, f"Could not read predicted output: {e}")

    # Check that the file has substantial content
    if len(content.strip()) < 50:
        return (False, "Predicted output file has too little content")

    # Get species columns from concentration data
    conc_species = [col for col in conc_df.columns if col != 'TIME']

    # Get reaction columns from IRR data
    irr_reactions = [col for col in irr_df.columns if col != 'TIME']

    # Check 1: Verify concentration data is present
    # At least some concentration species names should appear in the output
    species_found = 0
    for sp in conc_species:
        if sp in content:
            species_found += 1

    if species_found == 0:
        return (False, f"No concentration species ({conc_species}) found in output")

    if species_found < len(conc_species) * 0.5:
        return (False, f"Only {species_found}/{len(conc_species)} concentration species found in output")

    # Check 2: Verify IRR/reaction data is present
    rxn_found = 0
    for rxn in irr_reactions:
        if rxn in content:
            rxn_found += 1

    if rxn_found == 0:
        return (False, f"No reaction names ({irr_reactions}) found in output")

    # Check 3: Verify numerical values from concentration data appear
    # Check that at least some actual concentration values appear in the output
    def find_value_in_content(value, content, tolerance_pct=1.0):
        """Check if a numeric value (or close approximation) appears in the content."""
        # Convert to string and search for it
        val_str = str(value)
        if val_str in content:
            return True
        # Try formatted versions
        for fmt in [f"{value:.4f}", f"{value:.3f}", f"{value:.2f}", f"{value:.6f}", f"{value:.1f}", f"{int(value)}"]:
            if fmt in content:
                return True
        # Search for any number close to this value
        numbers = re.findall(r'-?\d+\.?\d*(?:[eE][+-]?\d+)?', content)
        for num_str in numbers:
            try:
                num = float(num_str)
                if abs(value) > 1e-10:
                    if abs(num - value) / abs(value) < tolerance_pct / 100:
                        return True
                else:
                    if abs(num - value) < 1e-6:
                        return True
            except ValueError:
                continue
        return False

    # Check that time values from concentration data appear
    time_values_found = 0
    for t in conc_df['TIME'].values[:5]:  # Check first 5 time values
        if find_value_in_content(t, content):
            time_values_found += 1

    if time_values_found == 0 and len(conc_df) > 0:
        # Be lenient - maybe time format is different
        pass  # Don't fail on this alone

    # Check 4: Verify that the output contains some actual concentration values
    # Check first concentration value of first species
    if len(conc_species) > 0 and len(conc_df) > 0:
        first_sp = conc_species[0]
        first_val = conc_df[first_sp].iloc[0]
        if not find_value_in_content(first_val, content, tolerance_pct=5.0):
            # Try to find any value from the concentration data
            found_any = False
            for sp in conc_species[:3]:
                for val in conc_df[sp].values[:3]:
                    if find_value_in_content(val, content, tolerance_pct=5.0):
                        found_any = True
                        break
                if found_any:
                    break
            if not found_any:
                return (False, "No concentration values from source data found in output")

    # Check 5: Verify that merged/IPR analysis is present
    # Look for keywords indicating merged analysis
    merged_keywords = ['initial', 'final', 'change', 'Initial', 'Final', 'Change', 
                       'INITIAL', 'FINAL', 'CHANGE', 'IPR', 'ipr', 'merged', 'MERGED',
                       'MERGE', 'combined', 'COMBINED']

    merged_found = any(kw in content for kw in merged_keywords)

    if not merged_found:
        return (False, "No merged/IPR analysis section found in output (missing keywords like 'initial', 'final', 'change')")

    # Check 6: Verify initial and final concentration values are correct
    # For each species, check that initial and final values appear
    if len(conc_species) > 0 and len(conc_df) > 0:
        sp = conc_species[0]
        initial_val = conc_df[sp].iloc[0]
        final_val = conc_df[sp].iloc[-1]
        change_val = final_val - initial_val

        initial_found = find_value_in_content(initial_val, content, tolerance_pct=5.0)
        final_found = find_value_in_content(final_val, content, tolerance_pct=5.0)

        if not initial_found and not final_found:
            return (False, f"Neither initial ({initial_val}) nor final ({final_val}) value for {sp} found in output")

    # Check 7: Verify IRR values appear in output
    if len(irr_reactions) > 0 and len(irr_df) > 0:
        rxn = irr_reactions[0]
        irr_val = irr_df[rxn].iloc[0]

        # IRR values might be converted to per-hour units
        # Check both original and converted values
        irr_found = (find_value_in_content(irr_val, content, tolerance_pct=5.0) or
                     find_value_in_content(irr_val * 3600, content, tolerance_pct=5.0) or
                     find_value_in_content(irr_val / 3600, content, tolerance_pct=5.0))

        if not irr_found:
            # Be lenient - maybe the format is very different
            # Just check that some numbers appear
            numbers_in_content = re.findall(r'-?\d+\.?\d*(?:[eE][+-]?\d+)?', content)
            if len(numbers_in_content) < 10:
                return (False, "Output contains very few numerical values - IRR data may not be properly included")

    # Check 8: Verify output has multiple sections/analyses
    # Count distinct sections or headers
    section_indicators = ['[', '===', '---', 'Analysis', 'ANALYSIS', 'Section', 'SECTION']
    sections_found = sum(1 for ind in section_indicators if ind in content)

    lines = content.strip().split('\n')
    if len(lines) < 5:
        return (False, f"Output has too few lines ({len(lines)}) - expected comprehensive results")

    # Check 9: Verify the three types of analysis are present
    # Concentration-only analysis
    conc_analysis_keywords = ['CONCENTRATION', 'Concentration', 'conc', 'CONC']
    conc_analysis_found = any(kw in content for kw in conc_analysis_keywords)

    # IRR-only analysis  
    irr_analysis_keywords = ['IRR', 'irr', 'REACTION', 'Reaction', 'reaction', 'RXN', 'rate', 'RATE']
    irr_analysis_found = any(kw in content for kw in irr_analysis_keywords)

    if not conc_analysis_found:
        return (False, "No concentration analysis section found in output")

    if not irr_analysis_found:
        return (False, "No IRR/reaction rate analysis section found in output")

    # All checks passed
    checks_summary = []
    checks_summary.append(f"Species found: {species_found}/{len(conc_species)}")
    checks_summary.append(f"Reactions found: {rxn_found}/{len(irr_reactions)}")
    checks_summary.append(f"Output lines: {len(lines)}")
    checks_summary.append("Concentration analysis: present")
    checks_summary.append("IRR analysis: present")
    checks_summary.append("Merged/IPR analysis: present")

    return (True, "All checks passed: " + "; ".join(checks_summary))


