    print(f"Reason: {reason}")

import pandas as pd
import yaml
import os
import re


def eval():
    pred_path = "pred_results/pred_add_cores_to_linker.csv"
    config_path = "benchmark/datasets/ChemTSv2/config/setting_linker.yaml"
    csv_path = "benchmark/datasets/ChemTSv2/result_C1.0.csv"

    # Load configuration to understand expected cores
    try:
        with open(config_path, 'r') as <local-path>            config = yaml.safe_load(f)
        cores = config.get('cores', [])
    except Exception as <local-path>        return (False, f"Failed to load config: {e}")

    if not cores:
        return (False, "No cores found in config file")

    # Load original CSV
    try:
        orig_df = pd.read_csv(csv_path)
    except Exception as <local-path>        return (False, f"Failed to load original CSV: {e}")

    # Load predicted results
    try:
        pred_df = pd.read_csv(pred_path)
    except Exception as <local-path>        return (False, f"Failed to load predicted results: {e}")

    # Check required columns
    required_cols = {"smiles", "smiles_w_cores"}
    if not required_cols.issubset(set(pred_df.columns)):
        missing = required_cols - set(pred_df.columns)
        return (False, f"Missing required columns: {missing}")

    # Check row count matches original
    if len(pred_df) != len(orig_df):
        return (False, f"Row count mismatch: predicted has {len(pred_df)} rows, original has {len(orig_df)} rows")

    # Check original smiles column is preserved
    if 'smiles' in orig_df.columns:
        if not pred_df["smiles"].equals(orig_df["smiles"]):
            # Try reset index comparison
            orig_smiles = orig_df["smiles"].reset_index(drop=True)
            pred_smiles = pred_df["smiles"].reset_index(drop=True)
            if not orig_smiles.equals(pred_smiles):
                return (False, "The 'smiles' column does not match the original data")

    # Check smiles_w_cores column has values
    pred_valid_mask = pred_df["smiles_w_cores"].notna()
    pred_valid_count = pred_valid_mask.sum()

    if pred_valid_count == 0:
        return (False, "No valid smiles_w_cores entries found")

    total_rows = len(pred_df)
    completion_rate = pred_valid_count / total_rows
    if completion_rate < 0.5:
        return (False, f"Too few smiles_w_cores entries: {pred_valid_count}/{total_rows} ({completion_rate:.1%})")

    # Count number of wildcards in original linkers
    num_cores = len(cores)

    # Check that cores were actually incorporated into the results
    # Strategy: verify that core fragments appear in the result SMILES
    # and that wildcards were replaced

    cores_attached_count = 0
    wildcard_reduced_count = 0
    cores_present_count = 0

    # Extract non-wildcard parts of cores for checking
    # Remove * from cores to get the actual chemical fragments
    core_fragments = []
    for core in cores:
        # Get a meaningful substring from the core (at least 3 chars)
        fragment = core.replace('*', '').strip()
        if len(fragment) >= 3:
            core_fragments.append(fragment)

    for idx, row in pred_df[pred_valid_mask].iterrows():
        original_smi = str(row['smiles'])
        result_smi = str(row['smiles_w_cores'])

        original_wildcards = original_smi.count('*')
        result_wildcards = result_smi.count('*')

        # Check wildcards were reduced
        if result_wildcards < original_wildcards:
            wildcard_reduced_count += 1

        # Check that result is longer (cores were added)
        if len(result_smi) > len(original_smi):
            cores_attached_count += 1

        # Check that at least one core fragment appears in result
        for fragment in core_fragments:
            if len(fragment) >= 3 and fragment in result_smi:
                cores_present_count += 1
                break

    # At least 50% of rows should show evidence of core attachment
    attachment_rate = cores_attached_count / pred_valid_count if pred_valid_count > 0 else 0
    wildcard_rate = wildcard_reduced_count / pred_valid_count if pred_valid_count > 0 else 0

    if attachment_rate < 0.5 and wildcard_rate < 0.5:
        return (False, f"Insufficient evidence of core attachment: "
                f"only {attachment_rate:.1%} rows show longer SMILES, "
                f"{wildcard_rate:.1%} show reduced wildcards")

    # Try RDKit validation if available
    try:
        from rdkit import Chem
        use_rdkit = True
    except Exception:
        use_rdkit = False

    valid_mol_count = 0
    invalid_mol_count = 0

    if use_rdkit:
        for idx, row in pred_df[pred_valid_mask].iterrows():
            result_smi = str(row['smiles_w_cores'])
            try:
                mol = Chem.MolFromSmiles(result_smi)
                if mol is not None:
                    valid_mol_count += 1
                else:
                    invalid_mol_count += 1
            except Exception:
                invalid_mol_count += 1

        validity_rate = valid_mol_count / pred_valid_count if pred_valid_count > 0 else 0

        # Be lenient - simple string replacement may not always produce valid SMILES
        # but should produce valid ones for most cases
        if validity_rate < 0.3:
            return (False, f"Too few valid molecules in smiles_w_cores: "
                    f"{valid_mol_count}/{pred_valid_count} ({validity_rate:.1%}) are valid SMILES")

        # Check that cores appear in valid molecules
        # Verify by checking that core SMILES fragments are substructures
        core_substructure_count = 0
        total_checked = 0

        for idx, row in pred_df[pred_valid_mask].head(50).iterrows():
            result_smi = str(row['smiles_w_cores'])
            result_mol = Chem.MolFromSmiles(result_smi)
            if result_mol is None:
                continue
            total_checked += 1

            # Check if any core is a substructure of the result
            for core in cores:
                core_clean = core.replace('*', '[*]') if '*' in core else core
                # Try to parse core as a molecule (replace * with dummy atom)
                core_smi_test = core.replace('[*]', '[H]').replace('*', '[H]')
                core_mol = Chem.MolFromSmiles(core_smi_test)
                if core_mol is not None and result_mol.HasSubstructMatch(core_mol):
                    core_substructure_count += 1
                    break

        if total_checked > 0:
            substructure_rate = core_substructure_count / total_checked
            # This check is informational - don't fail on it since attachment 
            # method may vary

    # Final summary
    summary_parts = [
        f"{pred_valid_count}/{total_rows} rows processed",
        f"{attachment_rate:.1%} show core attachment (longer SMILES)",
        f"{wildcard_rate:.1%} show reduced wildcards",
    ]

    if use_rdkit and pred_valid_count > 0:
        validity_rate = valid_mol_count / pred_valid_count
        summary_parts.append(f"{validity_rate:.1%} valid SMILES")

    # Check that the overall wildcard count was reduced
    total_original_wildcards = sum(
        str(row['smiles']).count('*')
        for _, row in pred_df.iterrows()
        if pd.notna(row['smiles'])
    )
    total_result_wildcards = sum(
        str(row['smiles_w_cores']).count('*')
        for _, row in pred_df[pred_valid_mask].iterrows()
    )

    if total_original_wildcards > 0 and total_result_wildcards >= total_original_wildcards:
        return (False, f"Wildcards not reduced after core attachment: "
                f"original={total_original_wildcards}, result={total_result_wildcards}")

    # Check molecules got larger on average
    avg_original_len = pred_df['smiles'].apply(lambda x: len(str(x))).mean()
    avg_result_len = pred_df[pred_valid_mask]['smiles_w_cores'].apply(lambda x: len(str(x))).mean()

    if avg_result_len <= avg_original_len:
        return (False, f"Result molecules not larger than linkers on average: "
                f"avg linker={avg_original_len:.1f}, avg result={avg_result_len:.1f}")

    return (True, f"Core attachment successful: {', '.join(summary_parts)}")


